SETORES_DESCRICAO = {
    "CAA": "Coordenadoria de Administração e Almoxarifado",
    "CCF": "Coordenadoria de Contabilidade e Finanças",
    "CCS": "Coordenadoria de Comunicação Social",
    "CEAF": "Centro de Apoio às Funções Essenciais",
    "CLC": "Coordenadoria de Licitações e Contratos",
    "CPPT": "Coordenadoria de Planejamento, Projetos e TI",
    "CRH": "Coordenadoria de Recursos Humanos",
    "CTI": "Coordenadoria de Tecnologia da Informação",
    "GAECO": "Grupo de Atuação Especial de Combate ao Crime Organizado",
    "GSI": "Gabinete do Subprocurador Institucional",
    "ASSESPPLAGES": "Assessoria de Planejamento e Gestão",
}


class Command(BaseCommand):
    help = "Importa 308 itens do PCA 2026 MPPI (extraídos do PDF Versão 3.0)"

    def add_arguments(self, parser):
        parser.add_argument("--dry-run", action="store_true", help="Não grava, apenas mostra o resumo")
        parser.add_argument("--limpar", action="store_true", help="Remove PCA 2026 existente antes de importar")
        parser.add_argument("--admin-username", default="admin")

    def handle(self, *args, **options):
        dry_run = options["dry_run"]
        limpar = options["limpar"]

        if dry_run:
            self.stdout.write(self.style.WARNING("=== DRY-RUN — nada será gravado ===\n"))
            setores = {}
            for item in ITENS_PCA2026:
                setores.setdefault(item["setor"], []).append(item)
            for s, lista in sorted(setores.items()):
                valor = sum(x["vtotal"] for x in lista)
                self.stdout.write(f"  {s}: {len(lista)} itens — R$ {valor:,.2f}")
            total = sum(x["vtotal"] for x in ITENS_PCA2026)
            self.stdout.write(f"\nTotal: {len(ITENS_PCA2026)} itens — R$ {total:,.2f}")
            return

        try:
            admin = User.objects.get(username=options["admin_username"])
        except User.DoesNotExist:
            admin = User.objects.filter(is_superuser=True).first()

        with transaction.atomic():
            # Órgão
            orgao, _ = Orgao.objects.get_or_create(
                sigla="MPPI",
                defaults={
                    "nome": "Ministério Público do Estado do Piauí",
                    "uf": "PI",
                    "esfera": "estadual",
                    "ativo": True,
                },
            )
            self.stdout.write(f"Órgão: {orgao}")

            # PCA 2026
            if limpar:
                PlanoContratacaoAnual.objects.filter(orgao=orgao, exercicio=2026).delete()
                self.stdout.write(self.style.WARNING("PCA 2026 removido."))

            pca, pca_criado = PlanoContratacaoAnual.objects.get_or_create(
                orgao=orgao,
                exercicio=2026,
                defaults={
                    "status": "aprovado",
                    "prazo_coleta_inicio": "2025-07-10",
                    "prazo_coleta_fim": "2025-07-30",
                    "prazo_consolidacao_fim": "2025-08-20",
                    "prazo_aprovacao_fim": "2025-09-30",
                },
            )
            self.stdout.write(f"PCA 2026: {'criado' if pca_criado else 'já existia'}")

            # Unidades e DFDs por setor
            setores = {}
            for item in ITENS_PCA2026:
                setores.setdefault(item["setor"], []).append(item)

            dfd_count = 0
            item_count = 0

            for setor, lista in sorted(setores.items()):
                nome_setor = SETORES_DESCRICAO.get(setor, setor)

                unidade, _ = UnidadeRequisitante.objects.get_or_create(
                    orgao=orgao,
                    sigla=setor,
                    defaults={"nome": nome_setor, "ativo": True},
                )

                valor_setor = sum(x["vtotal"] for x in lista)
                dfd, dfd_criado = DocumentoFormalizacaoDemanda.objects.get_or_create(
                    pca=pca,
                    unidade=unidade,
                    defaults={
                        "descricao_objeto": f"Demandas do setor {setor} — PCA 2026",
                        "justificativa": (
                            f"Demandas consolidadas do setor {nome_setor} para o "
                            f"exercício 2026, conforme PCA 2026 Versão 3.0 aprovado pelo PGJ/MPPI."
                        ),
                        "prazo_necessidade": "2026-12-31",
                        "grau_prioridade": "alto" if any(x["prioridade"] == "alto" for x in lista) else "medio",
                        "status": "aprovado",
                        "requisitante": admin,
                    },
                )
                if dfd_criado:
                    dfd_count += 1

                # Itens
                numero = ItemPCA.objects.filter(dfd=dfd).count() + 1
                for row in lista:
                    _, criado = ItemPCA.objects.get_or_create(
                        dfd=dfd,
                        numero_item=numero,
                        defaults={
                            "categoria": "solucao_ti" if setor == "CTI" else "servico" if "Serv" in row["descricao"][:20] else "material",
                            "descricao": row["descricao"][:500],
                            "codigo_catmat_catser": row["codigo"],
                            "unidade_fornecimento": "UN",
                            "quantidade_estimada": row["qtd"],
                            "valor_unitario_estimado": row["vunit"],
                            "valor_total_estimado": row["vtotal"],
                            "tipo_contratacao": row["tipo_contratacao"],
                            "data_pretendida_conclusao": row["conclusao"],
                            "observacoes": f"Tipo: {row['tipo_contratacao']} | Código PCA: {row['codigo']} | Setor: {row['setor']} | UO: {row['uo']}",
                        },
                    )
                    if criado:
                        item_count += 1
                        numero += 1

                self.stdout.write(
                    f"  {setor}: {len(lista)} itens — R$ {valor_setor:,.2f}"
                    + (" (DFD criado)" if dfd_criado else "")
                )

            total = sum(x["vtotal"] for x in ITENS_PCA2026)
            self.stdout.write(self.style.SUCCESS(
                f"\nImportação concluída!"
                f"\n  PCAs:   1 (exercício 2026)"
                f"\n  DFDs:   {dfd_count}"
                f"\n  Itens:  {item_count}"
                f"\n  Valor:  R$ {total:,.2f}"
            ))
